import React from "react";

function Projects() {
  return (
    <div className="projects">
      <h2>My Projects</h2>
      <ul>
        <li><strong>AuraTech</strong> — E-Commerce website built with React and JSON data handling.</li>
        <li><strong>POS Library System</strong> — Java-based point of sale system with GUI.</li>
        <li><strong>Learning Management System</strong> — Java app managing course materials and users.</li>
      </ul>
    </div>
  );
}

export default Projects;
